-sm text-muted-foreground"><p>{{ candidate.name }} · {{ $t('liveSolo.selection.unavailable') }}</p><p v-for="reason in candidate.reasons" :key="reason.value">{{ $t(reason.label) }}</p></div><section v-if="selectionUses.length" class="flex flex-col gap-2"><h3 class="text-sm font-semibold">{{ $t('liveSolo.selection.uses') }}</h3><Button v-for="use in selectionUses" :key="use.roundId" variant="ghost" size="sm" class="h-auto whitespace-normal justify-start text-left" @click="openUsage(use.matchId!)">{{ $t('liveSolo.round', { number: use.number ?? 1 }) }} · {{ $t(use.openedAt ? 'liveSolo.review.opened' : 'liveSolo.selection.neverOpened') }}</Button></section></div><section v-for="resource in failedResources" :key="resource.questionId" class="flex flex-col gap-2"><h3 class="text-sm font-semibold">{{ $t('liveSolo.preparation.questionFailed', { position: (resource.position ?? 0) + 1 }) }}</h3><p v-if="resource.failureLabel" class="text-sm text-destructive">{{ $t(resource.failureLabel) }}</p><Button variant="outline" size="sm" :disabled="busy || !workspace?.allowedOperations?.includes('RetryPreparation')" @click="retryPreparation(resource.questionId)">{{ $t('liveSolo.preparation.retry') }}</Button></section><p v-if="!['Completed', 'Canceled'].includes(match?.state ?? '')" class="max-w-[70ch] text-sm text-muted-foreground">{{ $t(platformStreaming ? 'liveSolo.judge.screensRequired' : 'liveSolo.judge.noStreaming') }}</p><div class="flex flex-wrap gap-2"><Button v-if="workspace?.allowedOperations?.includes('PrepareRound')" :disabled="busy || !workspace?.allowedOperations?.includes('PrepareRound')" variant="outline" @click="prepareRound">{{ $t('liveSolo.judge.prepare') }}</Button><Button v-if="round?.state === 'Preparing'" :disabled="busy || !startAllowed" @click="start">{{ $t('liveSolo.judge.start') }}</Button><Button v-if="match?.state === 'Running' || match?.state === 'Countdown'" :disabled="busy" variant="outline" @click="openDecision('Pause')">{{ $t('liveSolo.judge.pause') }